INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Festlegen von Projektzielen Teil der Initiierung?', 2, '[{"text": "Ja", "correct": true, "because": "Ziele definieren den Projektstart"}, {"text": "Nein", "correct": false, "because": "Es ist zentral dafür"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal haben Projektziele in der Initiierung?', 3, '[{"text": "Klar und eindeutig", "correct": true, "because": "Vermeiden Missverständnisse"}, {"text": "Vage und flexibel", "correct": false, "because": "Fehlt Richtung"}, {"text": "Ohne Zeitbezug", "correct": false, "because": "Zeit ist oft enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektziele geben Orientierung. b) Ziele werden erst im Abschluss festgelegt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ziele gehören zur Initiierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden beim Festlegen von Projektzielen berücksichtigt?', 4, '[{"text": "Projektumfang", "correct": true, "because": "Definiert Zielgröße"}, {"text": "Teamgröße allein", "correct": false, "because": "Nicht primär entscheidend"}, {"text": "Zeitrahmen", "correct": true, "because": "Gibt zeitliche Grenze"}, {"text": "Kundenanforderungen", "correct": true, "because": "Richten Ziele aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne festgelegte Ziele starten?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele sind Grundlage"}, {"text": "Ja", "correct": false, "because": "Fehlt Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel ist in der Initiierung schlecht formuliert?', 3, '[{"text": "Irgendwas machen", "correct": true, "because": "Zu ungenau"}, {"text": "Software bis Q2 fertigstellen", "correct": false, "because": "Klar und spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Festlegen von Projektzielen nur für große Projekte nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Projekte wichtig"}, {"text": "Ja", "correct": false, "because": "Auch kleine Projekte brauchen Ziele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft beim Festlegen von Projektzielen?', 3, '[{"text": "SMART-Prinzip", "correct": true, "because": "Strukturiert Zielsetzung"}, {"text": "Keine Planung", "correct": false, "because": "Fehlt Struktur"}, {"text": "Zufällige Wahl", "correct": false, "because": "Ungeeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektziele müssen messbar sein. b) Ziele ändern sich in der Initiierung oft.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ziele werden festgelegt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Projektziele in der Initiierung?', 3, '[{"text": "Basis für Planung", "correct": true, "because": "Leiten weitere Schritte"}, {"text": "Optionale Orientierung", "correct": false, "because": "Sind zwingend"}, {"text": "Kostenreduktion", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Projektziele in der Initiierung vage bleiben?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit ist nötig"}, {"text": "Ja", "correct": false, "because": "Verwirrung entsteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein gut festgelegtes Projektziel?', 3, '[{"text": "App mit 5 Features bis Juni", "correct": true, "because": "Spezifisch und klar"}, {"text": "Irgendwann etwas verbessern", "correct": false, "because": "Zu ungenau"}, {"text": "Team zufriedenstellen", "correct": false, "because": "Nicht konkret"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Festlegen von Zielen nur eine формality?', 2, '[{"text": "Nein", "correct": true, "because": "Grundlage des Projekts"}, {"text": "Ja", "correct": false, "because": "Hat praktische Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fragen klären Projektziele in der Initiierung?', 4, '[{"text": "Was soll erreicht werden?", "correct": true, "because": "Definiert Ergebnis"}, {"text": "Wie hoch sind die Kosten?", "correct": false, "because": "Späterer Schritt"}, {"text": "Wann ist es fertig?", "correct": true, "because": "Zeitliche Komponente"}, {"text": "Wer ist verantwortlich?", "correct": true, "because": "Klarheit über Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Projektziele in der Initiierung schriftlich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit reicht aus"}, {"text": "Ja", "correct": false, "because": "Form ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor macht Ziele in der Initiierung unklar?', 3, '[{"text": "Fehlende Details", "correct": true, "because": "Verwirrung entsteht"}, {"text": "Klarer Zeitrahmen", "correct": false, "because": "Fördert Klarheit"}, {"text": "Konkrete Ergebnisse", "correct": false, "because": "Unterstützt Spezifität"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ziel in der Initiierung mehrere Teilziele haben?', 2, '[{"text": "Ja", "correct": true, "because": "Wenn spezifisch definiert"}, {"text": "Nein", "correct": false, "because": "Struktur erlaubt es"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt das Festlegen von Zielen?', 3, '[{"text": "Stakeholder-Abstimmung", "correct": true, "because": "Sichert Akzeptanz"}, {"text": "Keine Kommunikation", "correct": false, "because": "Führt zu Chaos"}, {"text": "Zufällige Entscheidung", "correct": false, "because": "Fehlt Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektziele sind in der Initiierung bindend. b) Ziele ignorieren Kundenwünsche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Kundenwünsche zählen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel des Festlegens von Projektzielen?', 3, '[{"text": "Einheitliche Ausrichtung", "correct": true, "because": "Fokussiert Team"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Struktur", "correct": false, "because": "Fördert Planung"}]');
